(function(E){ const x = E["ai-m4"] = E["ai-m4"] || {units:{}}; x.units["ai-14"] = {"grammar":{"id":"c-ai-14-g","level":"B1","course":"ai-internet","unit":"ai-14","title":"Talking about sources: published by, so it may be","titleTr":"Kaynaktan söz etmek: published by, so it may be","titleFa":"حرف زدن درباره‌ی منبع: published by، so it may be","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["It was published by...","It was published by a panel seller."],["so it may be...","so it may be biased."],["Another source confirms this.","Another source confirms the date."]]},"wrong":"It published by a seller.","right":"It was published by a seller.","blank":{"sentence":"It was ___ by a trade group.","word":"published","distractors":["publish","publishing"]},"wrong2":"Another source confirm this.","right2":"Another source confirms this.","blank2":{"sentence":"Another source ___ the date.","word":"confirms","distractors":["confirm","confirming"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Published by gives the writer.","tr":"published by yazarı söyler.","fa":"published by نویسنده را می‌گوید.","ex":"It was published by a ministry."},{"en":"Use may for what you can't be sure of.","tr":"Emin olamadığın şey için may kullan.","fa":"برای چیزی که مطمئن نیستی از may استفاده کن.","ex":"so it may be old."}],"test":{"en":"Do you know this for sure? If not, use may.","tr":"Bunu kesin biliyor musun? Bilmiyorsan may kullan.","fa":"این را قطعی می‌دانی؟ اگر نه، از may استفاده کن."}},"errorWatch":[{"find":["it published by"],"fix":{"en":"Use was: \"It was published by\".","tr":"was kullan: \"It was published by\".","fa":"از was استفاده کن: «It was published by»."}}]},"b2":{"id":"c-ai-14-b2","level":"B2","course":"ai-internet","unit":"ai-14","track":"B2","title":"Weighing sources: biased, independent, on the other hand","titleTr":"Kaynak tartmak: biased, independent, on the other hand","titleFa":"سنجیدن منبع: biased، independent، on the other hand","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["is likely to be biased","A seller's blog is likely to be biased."],["On the other hand,","On the other hand, its data is specific."]]},"wrong":"It is likely being biased.","right":"It is likely to be biased.","blank":{"sentence":"A seller's page is likely ___ be biased.","word":"to","distractors":["for","of"]},"wrong2":"In the other hand, it is recent.","right2":"On the other hand, it is recent.","blank2":{"sentence":"___ the other hand, its figures are clear.","word":"On","distractors":["In","At"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Biased means it favours one side.","tr":"biased bir tarafı kayırıyor demektir.","fa":"biased یعنی جانب یک طرف را گرفته.","ex":"a biased review"},{"en":"On the other hand adds the other side.","tr":"on the other hand diğer yönü ekler.","fa":"on the other hand روی دیگر قضیه را اضافه می‌کند.","ex":"On the other hand, it is recent."}],"test":{"en":"Have you given both sides?","tr":"İki tarafı da verdin mi?","fa":"هر دو روی قضیه را گفته‌ای؟"}},"errorWatch":[{"find":["in the other hand"],"fix":{"en":"Say \"on the other hand\".","tr":"\"on the other hand\" de.","fa":"بگو «on the other hand»."}}],"useIn":{"en":"B2: give both sides of one source with on the other hand.","tr":"B2: Bir kaynağın iki yönünü on the other hand ile ver.","fa":"B2: دو روی یک منبع را با on the other hand بگو."},"exitItem":{"from":"ai-14","kind":"blank","prompt":"It is old. ___ the other hand, it is independent.","options":["On","In","At"],"correct":0}},"vocab":{"id":"c-ai-14-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-14","goals":["career"],"title":{"en":"Judging a page","tr":"Sayfa değerlendirmek","fa":"سنجیدن صفحه"},"cards":[{"word":"independent","sentence":"We need an independent source.","meaning":{"en":"Not paid by or part of the seller.","tr":"Satıcıya bağlı olmayan.","fa":"وابسته به فروشنده نیست."}},{"word":"last updated","sentence":"Check the last updated date.","meaning":{"en":"The date of the newest change.","tr":"En son değişiklik tarihi.","fa":"تاریخ آخرین تغییر."}},{"word":"lateral reading","sentence":"Lateral reading means leaving the page.","meaning":{"en":"Checking a source from outside it.","tr":"Kaynağı dışarıdan kontrol etmek.","fa":"بررسی منبع از بیرون آن."}},{"word":"biased","sentence":"This review may be biased.","meaning":{"en":"Favouring one side.","tr":"Bir tarafı kayıran.","fa":"جانبدار یک طرف."}}]},"judge":{"id":"c-ai-14-j","course":"ai-internet","unit":"ai-14","type":"judge","title":{"en":"What does each note say?","tr":"Her not ne söylüyor?","fa":"هر یادداشت چه می‌گوید؟"},"prompt":"Read each note about a page. Which questions does it answer?","parts":["Who","When","Why"],"instruction":{"en":"Tap every question the note answers.","tr":"Notun yanıtladığı her soruya dokun.","fa":"روی هر سؤالی که یادداشت جواب داده بزن."},"items":[{"by":"Example note","answer":"It looks very professional and has nice photos.","present":[],"fix":{"en":"Looks tell you nothing about who, when or why.","tr":"Görünüş kim, ne zaman, neden hakkında bir şey söylemez.","fa":"ظاهر چیزی درباره‌ی چه کسی، کی و چرا نمی‌گوید."}},{"by":"Example note","answer":"It was published by the ministry in 2026.","present":["Who","When"],"fix":{"en":"Why? Say what it is for.","tr":"Neden? Ne için olduğunu söyle.","fa":"چرا؟ بگو برای چیست."}},{"by":"Good model","answer":"A panel seller wrote this in 2019 to sell its own panels.","present":["Who","When","Why"],"fix":null},{"by":"Example note","answer":"It is an advert for a panel maker.","present":["Who","Why"],"fix":{"en":"Check when it was last updated.","tr":"Son güncellemeye bak.","fa":"ببین آخرین بار کی به‌روز شده."}}]},"speaking":{"id":"ai-14","course":"ai-internet","unit":"ai-14","topic":{"en":"Explain why you trust a source","tr":"Bir kaynağa neden güvendiğini açıkla","fa":"توضیح بده چرا به یک منبع اعتماد داری"},"warmup":{"en":"Which website do you trust most for your work? Why?","tr":"İşin için en çok hangi siteye güvenirsin? Neden?","fa":"برای کارت به کدام سایت بیشتر اعتماد داری؟ چرا؟"},"questions":[{"en":"Tell a colleague why you would or wouldn't use one page: who, when and why.","tr":"Bir meslektaşına bir sayfayı neden kullanıp kullanmayacağını söyle: kim, ne zaman, neden.","fa":"به همکارت بگو چرا یک صفحه را به کار می‌بری یا نمی‌بری: چه کسی، کی و چرا."},{"en":"Your manager says: \"AI can choose who we interview.\" Say what worries you, and what you suggest.","tr":"Yöneticin diyor ki: \"AI can choose who we interview.\" Seni neyin endişelendirdiğini ve ne önerdiğini söyle.","fa":"مدیرت می‌گوید: «AI can choose who we interview.» بگو چه چیزی نگرانت می‌کند و چه پیشنهادی داری."},{"en":"Explain the swap test to a colleague, with one example.","tr":"Değiştirme testini bir meslektaşına bir örnekle anlat.","fa":"آزمون جابه‌جایی را با یک مثال برای همکارت توضیح بده."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"It was published by...","meaning":{"en":"Names the writer.","tr":"Yazarı söyler.","fa":"نویسنده را می‌گوید."}},{"phrase":"Another source confirms...","meaning":{"en":"Shows a second check.","tr":"İkinci bir kontrolü gösterir.","fa":"بررسی دوم را نشان می‌دهد."}}],"model":"I wouldn't use this page for our report. It was published by a company that sells these panels, and it was last updated in 2019, so it may be old and biased. It means that we need another source. Instead, use the maker's datasheet. It is newer, and another source confirms its figures.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I covered who, when and why.","tr":"Kim, ne zaman ve neden sorularını kapsadım.","fa":"گفتم چه کسی، کی و چرا."}]},"writing":{"id":"c-ai-14-w","title":{"en":"Rank three pages","tr":"Üç sayfayı sırala","fa":"سه صفحه را رتبه‌بندی کن"},"course":"ai-internet","unit":"ai-14","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"You need to know how long a solar panel lasts. Rank these and give a reason for each: (A) a seller's blog, 2019; (B) the maker's datasheet, 2026; (C) a forum thread from users, 2025.","tr":"Bir güneş panelinin ne kadar dayandığını öğrenmek istiyorsun. Sırala ve her biri için neden ver: (A) satıcı blogu, 2019; (B) üreticinin teknik föyü, 2026; (C) kullanıcıların forum başlığı, 2025.","fa":"می‌خواهی بدانی پنل خورشیدی چقدر دوام می‌آورد. این‌ها را رتبه‌بندی کن و برای هر کدام دلیل بیاور: (A) وبلاگ فروشنده، ۲۰۱۹؛ (B) دیتاشیت سازنده، ۲۰۲۶؛ (C) بحث کاربران در فروم، ۲۰۲۵."},"model":"First: B. It was published by the maker in 2026, so it is recent, and it has exact figures. Second: C. It is real experience, but it is unverified. Another source must confirm it. Third: A. It was published by a seller in 2019, so it may be biased and old.","frame":"First: ___. It was published by ___, so ___.\nSecond: ___. It ___, but ___.\nThird: ___. It was published by ___, so it may be ___.","words":[{"word":"published by"},{"word":"so it may be"}],"minWords":30,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Give both sides of one source with on the other hand.","tr":"B2 yolu: hazır çerçeve yok. Bir kaynağın iki yönünü on the other hand ile ver.","fa":"مسیر B2: چارچوب آماده نداری. دو روی یک منبع را با on the other hand بگو."},"own":{"en":"Now judge one page you used for work this month.","tr":"Şimdi bu ay iş için kullandığın bir sayfayı değerlendir.","fa":"حالا یک صفحه را که این ماه برای کار استفاده کرده‌ای بسنج."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Ask an AI search tool who published its sources, then check one yourself.","tr":"Yapay zekâlı arama aracına kaynaklarını kimin yayımladığını sor, sonra birini kendin kontrol et.","fa":"از ابزار جست‌وجو بپرس منبع‌هایش را چه کسی منتشر کرده و یکی را خودت بررسی کن."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"Use the three example pages above. No tool is needed.","tr":"Yukarıdaki üç örnek sayfayı kullan. Araç gerekmez.","fa":"از سه صفحه‌ی نمونه‌ی بالا استفاده کن. ابزاری لازم نیست."},"noTool":true}]},"exit":{"id":"c-ai-14-x","course":"ai-internet","unit":"ai-14","type":"exit","items":[{"from":"ai-14","kind":"mcq","prompt":"A seller's page says its door is \"the best\". What can you use it for?","options":["Specifications, not \"best\"","Proof that it is the best","Nothing at all"],"correct":0,"why":{"en":"It is selling, so it may be biased.","tr":"Satıyor, taraflı olabilir.","fa":"می‌فروشد، پس شاید جانبدار باشد."},"point":1},{"from":"ai-14","kind":"blank","prompt":"It was ___ by a trade group in 2024.","options":["published","publish","publishing"],"correct":0,"why":{"en":"It was + past participle.","tr":"It was + üçüncü hâl.","fa":"It was + شکل سوم فعل."},"point":3},{"from":"ai-14","kind":"mcq","prompt":"What is the first thing to do after the three questions?","options":["Copy the page's main points into a note.","Leave the page and see what others say.","Read the same page again more slowly."],"correct":1,"why":{"en":"This is lateral reading.","tr":"Buna lateral reading denir.","fa":"به این lateral reading می‌گویند."},"point":1},{"from":"ai-13","kind":"mcq","prompt":"For what a rule says, where do you start?","options":["A seller's blog about the rule","The standards body or ministry","A forum of people in that trade"],"correct":1,"why":{"en":"Go to who wrote the rule.","tr":"Kuralı yazana git.","fa":"سراغ نویسنده‌ی قانون برو."}},{"from":"ai-11","kind":"mcq","prompt":"Which is the plain version of \"leverage\"?","options":["lift","use","levers"],"correct":1,"why":{"en":"Choose the short, common word.","tr":"Kısa, yaygın kelimeyi seç.","fa":"کلمه‌ی کوتاه و رایج را انتخاب کن."}},{"from":"ai-6","kind":"blank","prompt":"The prompt ___ say who it is for.","options":["doesn't","don't","isn't"],"correct":0,"why":{"en":"The pattern is: it doesn't say.","tr":"Kalıp şu: It doesn't say.","fa":"الگو این است: It doesn't say."}},{"from":"ai-14","kind":"mcq","prompt":"Your company wants AI to rank 200 CVs and reject the lowest. What do you say?","options":["It's fine, if the CVs are in good English.","A person must decide, and we test it.","It's fair, because a machine has no opinion."],"correct":1,"why":{"en":"AI can repeat human unfairness. It helps, but it doesn't decide about people.","tr":"Yapay zekâ insanların haksızlığını tekrar edebilir. Yardım eder ama insanlar hakkında karar vermez.","fa":"هوش مصنوعی ممکن است بی‌عدالتی انسان‌ها را تکرار کند. کمک می‌کند، ولی درباره‌ی آدم‌ها تصمیم نمی‌گیرد."},"point":2}]},"explain":{"id":"c-ai-14-e","course":"ai-internet","unit":"ai-14","type":"explain","level":"B1","title":{"en":"Who says so?","tr":"Bunu kim söylüyor?","fa":"چه کسی این را می‌گوید؟"},"objective":{"en":"In this lesson you will learn to judge a source with three questions and by checking it from outside.","tr":"Bu derste bir kaynağı üç soruyla ve dışarıdan kontrol ederek değerlendirmeyi öğreneceksin.","fa":"در این درس یاد می‌گیری منبع را با سه سؤال و با بررسی از بیرون بسنجی."},"hook":{"en":"A page can look very professional and still be selling you something. Don't judge it only from inside.","tr":"Bir sayfa çok profesyonel görünüp yine de sana bir şey satıyor olabilir. Yalnızca içinden bakarak değerlendirme.","fa":"یک صفحه می‌تواند خیلی حرفه‌ای به نظر برسد و باز چیزی به تو بفروشد. فقط از داخلش قضاوت نکن."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"20"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"head":{"en":"Three questions, then leave the page","tr":"Üç soru, sonra sayfadan çık","fa":"سه سؤال و بعد بیرون رفتن از صفحه"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"steps":[{"en":"Who wrote it?","tr":"Kim yazdı?","fa":"چه کسی نوشته؟","ex":"Published by a panel seller."},{"en":"When?","tr":"Ne zaman?","fa":"کی؟","ex":"Last updated in 2019."},{"en":"Why? Is it selling something?","tr":"Neden? Bir şey mi satıyor?","fa":"چرا؟ چیزی می‌فروشد؟","ex":"\"The best solar panel\""},{"en":"Leave the page. Search the organisation's name with \"review\" or \"about\".","tr":"Sayfadan çık. Kurumun adını \"review\" ya da \"about\" ile ara.","fa":"از صفحه بیرون برو. نام سازمان را با «⁨review⁩» یا «⁨about⁩» جست‌وجو کن.","ex":"SunPanels review"}],"tip":{"en":"This is called lateral reading: checking a source from outside it. A seller's page is useful for specifications, but not for \"best\".","tr":"Buna lateral reading denir: Kaynağı dışarıdan kontrol etmek. Satıcı sayfası teknik bilgi için yararlıdır, \"en iyi\" için değil.","fa":"به این ⁨lateral reading⁩ می‌گویند: بررسی منبع از بیرون آن. صفحه‌ی فروشنده برای مشخصات مفید است، نه برای «بهترین»."}},{"head":{"en":"AI can be biased too","tr":"Yapay zekâ da taraflı olabilir","fa":"هوش مصنوعی هم ممکن است جانبدار باشد"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"AI learned from human text, so it can repeat human unfairness. In a 2024 University of Washington test, three AI models ranked CVs differently when only the name changed. These were research models, but the risk is real.","tr":"Yapay zekâ insan metinlerinden öğrendi, bu yüzden insanların haksızlığını tekrar edebilir. 2024'te University of Washington'ın bir testinde üç yapay zekâ modeli, yalnızca ad değiştiğinde özgeçmişleri farklı sıraladı. Bunlar araştırma modelleriydi ama risk gerçektir.","fa":"هوش مصنوعی از متن‌های انسانی یاد گرفته، پس ممکن است بی‌عدالتی انسان‌ها را تکرار کند. در آزمایشی در سال ۲۰۲۴ در ⁨University of Washington⁩، سه مدل هوش مصنوعی وقتی فقط اسم عوض می‌شد رزومه‌ها را جور دیگری رتبه‌بندی کردند. این‌ها مدل‌های پژوهشی بودند، ولی خطرش واقعی است."},"steps":[{"en":"A person decides about people: hiring, pay, loans. AI only helps.","tr":"İnsanlar hakkında kararı insan verir: işe alım, maaş, kredi. Yapay zekâ yalnızca yardım eder.","fa":"درباره‌ی آدم‌ها، انسان تصمیم می‌گیرد: استخدام، حقوق، وام. هوش مصنوعی فقط کمک می‌کند.","ex":"Draft the questions. Don't rank the people."},{"en":"Do the swap test: change only a name, and compare.","tr":"Değiştirme testini yap: Yalnızca adı değiştir ve karşılaştır.","fa":"آزمون جابه‌جایی را انجام بده: فقط اسم را عوض کن و مقایسه کن.","ex":"The same letter for Ali, then for Ayşe."},{"en":"A different result? Don't use it, and tell someone.","tr":"Sonuç farklı mı? Kullanma ve birine söyle.","fa":"نتیجه فرق داشت؟ از آن استفاده نکن و به کسی بگو.","ex":"This may be biased."}],"phrases":[{"phrase":"Write this reference letter twice: once for Ali and once for Ayşe. Use the same facts. Then list every difference between the two letters.","meaning":{"en":"A swap test to copy.","tr":"Kopyalanacak bir değiştirme testi.","fa":"یک آزمون جابه‌جایی برای کپی."},"copy":true}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Talking about sources: published by, so it may be","tr":"Kaynaktan söz etmek: published by, so it may be","fa":"حرف زدن درباره‌ی منبع: ⁨published by⁩، ⁨so it may be⁩"},"steps":[{"en":"Published by gives the writer.","tr":"published by yazarı söyler.","fa":"⁨published by⁩ نویسنده را می‌گوید.","ex":"It was published by a ministry."},{"en":"Use may for what you can't be sure of.","tr":"Emin olamadığın şey için may kullan.","fa":"برای چیزی که مطمئن نیستی از ⁨may⁩ استفاده کن.","ex":"so it may be old."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["It was published by...","It was published by a panel seller."],["so it may be...","so it may be biased."],["Another source confirms this.","Another source confirms the date."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Judge one page","tr":"Bir sayfayı değerlendir","fa":"یک صفحه را بسنج"},"item":"Page: \"The best solar panel in the world!\" (the seller's own blog, 2019)","answer":"It was published by the seller, so it may be biased. It is useful for specifications, but not for \"best\". I would look for another source.","walk":[{"en":"Who wrote it? The seller.","tr":"Kim yazdı? Satıcı.","fa":"چه کسی نوشته؟ فروشنده."},{"en":"When, and why? 2019, and it is selling.","tr":"Ne zaman, neden? 2019, satış için.","fa":"کی و چرا؟ ۲۰۱۹، و برای فروش."},{"en":"Say what it is good for, and what next.","tr":"Neye yaradığını ve sonraki adımı söyle.","fa":"بگو به چه کاری می‌آید و قدم بعد چیست."}]},"quick":{"prompt":"What is lateral reading?","options":["Reading only the first paragraph of a page","Reading a page from left to right, line by line","Leaving a page to see what others say about it"],"correct":2,"why":{"en":"You check the source from outside.","tr":"Kaynağı dışarıdan kontrol edersin.","fa":"منبع را از بیرون بررسی می‌کنی."}},"remember":{"en":"Who wrote it, when, and why? Then leave the page and see what others say.","tr":"Kim yazdı, ne zaman, neden? Sonra sayfadan çık ve başkalarının ne dediğine bak.","fa":"چه کسی نوشته، کی و چرا؟ بعد از صفحه بیرون برو و ببین دیگران چه می‌گویند."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Weighing sources: biased, independent, on the other hand","tr":"Kaynak tartmak: biased, independent, on the other hand","fa":"سنجیدن منبع: ⁨biased⁩، ⁨independent⁩، ⁨on the other hand⁩"},"steps":[{"en":"Biased means it favours one side.","tr":"biased bir tarafı kayırıyor demektir.","fa":"⁨biased⁩ یعنی جانب یک طرف را گرفته.","ex":"a biased review"},{"en":"On the other hand adds the other side.","tr":"on the other hand diğer yönü ekler.","fa":"⁨on the other hand⁩ روی دیگر قضیه را اضافه می‌کند.","ex":"On the other hand, it is recent."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["is likely to be biased","A seller's blog is likely to be biased."],["On the other hand,","On the other hand, its data is specific."]]},"body":{"en":"B2: give both sides of one source with on the other hand.","tr":"B2: Bir kaynağın iki yönünü on the other hand ile ver.","fa":"⁨B2⁩: دو روی یک منبع را با ⁨on the other hand⁩ بگو."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
